<?php require __DIR__.'/../includes/bootstrap.php';if((int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0)exit('تم إعداد حساب الإدارة مسبقاً.');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(!defined('ADMIN_SETUP_KEY')||!hash_equals(ADMIN_SETUP_KEY,$_POST['setup_key']??''))$error='مفتاح التهيئة غير صحيح.';elseif(strlen($_POST['password']??'')<12)$error='اجعل كلمة المرور 12 حرفاً على الأقل.';else{$u=trim($_POST['username']??'');if($u==='')$error='اسم المستخدم مطلوب.';else{db()->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)')->execute([$u,password_hash($_POST['password'],PASSWORD_DEFAULT)]);go('login.php');}}}?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تهيئة مدير المتجر</title><link rel="stylesheet" href="../assets/css/store.css"></head><body><main class="inner login"><h1>إنشاء حساب المدير الأول</h1><p>استخدم مفتاح التهيئة الذي وضعته في config.php. احذف هذا الملف بعد إنشاء الحساب.</p><?php if($error):?><p class="notice"><?=h($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>مفتاح التهيئة<input name="setup_key" required></label><label>اسم المستخدم<input name="username" required></label><label>كلمة المرور (12 حرفاً على الأقل)<input type="password" name="password" minlength="12" required></label><button class="gold">إنشاء المدير</button></form></main></body></html>